#include "ratio.hpp"
int main(){try{ff::init();init_source();auto src=readRF("regenerated/ratio_source.dat");RF b=src[1]-scale(L0,3)*src[0];RF c=divRF(scale(L0*L0,3)*src[0]-scale(L0,2)*src[1]+src[2],t);for(F r:{145049,211895,211959}){auto bb=atEndpoint(b,r),cc=atEndpoint(c,r); auto aa=atEndpoint(src[0],r); Poly az=bb[1]*aa[0]-bb[0]*aa[1]; int av=0;while(av<=az.deg()&&!az.at(av))av++;az=exactdiv(az,Poly::mon(av)); if(!az.zero())az=scale(az,ff::inv(az.v.back()));std::cout<<"a-b resultant degree "<<az.deg()<<" valuation "<<av<<" pivot gcd "<<gcd(az,bb[1]).deg()<<" derivative gcd "<<gcd(az,derivative(az)).deg()<<"\n";std::ofstream af("regenerated/critical_content_"+std::to_string(r)+".dat");af<<"DOUBLE_CONTENT_V1\n"<<r<<"\n";writepoly(af,bb[0]);writepoly(af,bb[1]);writepoly(af,aa[0]);writepoly(af,aa[1]);writepoly(af,az);Poly z=bb[1]*cc[0]-bb[0]*cc[1];std::cout<<"root "<<r<<" bdegrees "<<bb[0].deg()<<","<<bb[1].deg()<<" cdegrees "<<cc[0].deg()<<","<<cc[1].deg()<<" resultant_degree "<<z.deg()<<"\n";int va=0;while(z.at(va)==0&&va<=z.deg())va++;z=exactdiv(z,Poly::mon(va));z=scale(z,ff::inv(z.v.back()));std::cout<<"valuation "<<va<<" remaining degree "<<z.deg()<<" gcd derivative "<<gcd(z,derivative(z)).deg()<<" pivot gcd "<<gcd(z,bb[1]).deg()<<"\n";std::cout<<"resultant ";printCoeffs(std::cout,z);std::cout<<"\n";std::ofstream f("regenerated/double_content_"+std::to_string(r)+".dat");f<<"DOUBLE_CONTENT_V1\n";f<<r<<"\n";writepoly(f,bb[0]);writepoly(f,bb[1]);writepoly(f,cc[0]);writepoly(f,cc[1]);writepoly(f,z);}}
catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
